css:
#tongsci2-2-1-2-2-cover .frame { flex-direction: row; gap: 72px; }
#tongsci2-2-1-2-2-cover .col-text { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 28px; }
#tongsci2-2-1-2-2-cover h1 { font-size: 112px; }
#tongsci2-2-1-2-2-cover .hero-pen { font-size: 56px; transform: rotate(-1.2deg); transform-origin: left center; margin-top: -6px; }
#tongsci2-2-1-2-2-cover .footer { left: 1100px; right: 300px; }
#tongsci2-2-1-2-2-cover .lesson-chip {
  align-self: flex-start; display: inline-flex; gap: 14px; align-items: baseline;
  border: 2px solid var(--ink); border-radius: 999px; padding: 6px 22px; font-size: 26px; font-weight: 600;
}
#tongsci2-2-1-2-2-cover .lesson-chip span { font-family: var(--f-mono); font-size: 22px; color: var(--ink-2); font-weight: 500; }
#tongsci2-2-1-2-2-cover .goals { display: flex; flex-direction: column; gap: 18px; max-width: 980px; }
#tongsci2-2-1-2-2-cover .goals-label { font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--ink-2); }
#tongsci2-2-1-2-2-cover .goal { display: grid; grid-template-columns: 52px 1fr; gap: 6px; font-size: 30px; line-height: 1.42; }
#tongsci2-2-1-2-2-cover .goal .no { font-family: var(--f-display); font-weight: 700; color: var(--ink-2); }
#tongsci2-2-1-2-2-cover .today {
  margin-top: 6px; padding: 20px 28px; background: var(--paper-2); border: 2px solid var(--ink);
  border-radius: 6px; box-shadow: 6px 6px 0 var(--ink); font-size: 32px; line-height: 1.45;
}
#tongsci2-2-1-2-2-cover .today .tag { display: block; font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--accent); margin-bottom: 6px; }
#tongsci2-2-1-2-2-cover .col-fig { flex: 0 0 700px; display: flex; flex-direction: column; gap: 14px; padding-top: 24px; }
#tongsci2-2-1-2-2-cover .fig-caption .cap { font-size: 21px; line-height: 1.4; }
#tongsci2-2-1-2-2-cover .share-card { padding: 60px 30px 26px; display: flex; flex-direction: column; gap: 18px; }
#tongsci2-2-1-2-2-cover .share-card h3 { margin: 0; font: 700 34px/1.3 var(--f-display); color: var(--ink); text-wrap: balance; }

js:
/* tongsci2.2-1-2.2.cover */
(function () {
  'use strict';
  const {part}=window.Deck;
  const mark=(r,n)=>{L1.steps(r,n,n===0?[1,2,3]:[1,2,3].filter(x=>x<n));L1.done(r,n===0);};
const single=r=>r.querySelectorAll('.share-opts button').forEach(b=>b.addEventListener('click',()=>r.querySelectorAll('.share-opts button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))));
const watch=(r,fn)=>{let t;return{setActive(on){clearInterval(t);if(on){fn();t=setInterval(fn,250);}}};};
const gallery=r=>{r.querySelector('.gv').addEventListener('gv-pick',e=>r.querySelectorAll('.lv-row').forEach(x=>x.classList.toggle('on',x.dataset.k===e.detail.b.dataset.row)));return RxT.gallery(r);};
const join=(...ps)=>RxT.join(...ps);
  part('tongsci2-2-1-2-2-cover',r=>{single(r);return PredSketch.mount(r)||{};});
})();
